<script>
 import {onMount,tick} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import {journalSession,journalDocument,journalEntry,journalVisibleEntries,journalAvailability} from './journal-state.js';
 import {journalMenus} from './journal-menus.js';
 import {createJournalNativeView} from './journal-native-view.js';
 import {fontCSSFamily} from './font-book-fonts.js';
 import './journal.css';
 let {state: journalState,profile,window:actualWindow=null,windowId=actualWindow?.id,controller,execute=null,oncommand=null,registerView=null,available=true,active=true,controls={}}=$props();
 let root=$state(null),message=$state(''),name=$state('My Journal'),format=$state('html'),passphrase=$state('');
 const session=$derived(journalSession(journalState,windowId)),doc=$derived(journalDocument(journalState,session?.documentId)),entry=$derived(journalEntry(doc,session?.entryId)),block=$derived(entry?.blocks.find(b=>b.id===session?.blockId)),cap=$derived(journalAvailability(profile)),menus=$derived(journalMenus(profile,journalState,windowId)),entries=$derived(session&&!session.locked?journalVisibleEntries(doc,session):[]),sources=$derived.by(()=>{journalState.revision;return controller?.sources?.(windowId)??{photos:[],files:[],fonts:[]};});
 let originalState,originalProfile,originalWindow,originalController,originalSession,originalId,retired=false;
 let mounted=$state(false);
 function owned(){return !retired&&root?.isConnected===true&&journalState===originalState&&profile===originalProfile&&actualWindow===originalWindow&&windowId===originalId&&controller===originalController&&session===originalSession;}
 function renderFont(name){const font=sources.fonts.find(f=>f.family===name||fontCSSFamily(f)===name);return font?fontCSSFamily(font):'system-ui';}
 const mediaNodes=new Set();
 function rememberMedia(event,a){const node=event.currentTarget;if(!owned()||session.locked||!entry?.attachments.includes(a)||node.getAttribute('src')!==a.content){node.pause();return;}mediaNodes.add(node);}
 $effect(()=>{journalState.revision;const locked=session?.locked;for(const node of mediaNodes){if(locked||!node.isConnected)node.pause();if(!node.isConnected)mediaNodes.delete(node);}});
 $effect(()=>{
  if(!mounted||session?.locked)return;journalState.revision;
  let cancelled=false;
  controller?.ensureFonts?.(windowId).then(result=>{if(!cancelled&&owned()&&result?.ok===false)message=result.error?.message??'Scene font unavailable; System fallback is displayed.';});
  return()=>{cancelled=true;};
 });
 async function run(suffix,payload={}){if(!owned()||!available||!active)return;const runner=oncommand??execute;const result=runner?await runner(`journal.${suffix}`,{windowId},payload):await controller?.handlers?.[`journal.${suffix}`]?.({windowId},payload);if(owned())message=result?.status==='applied'?'':result?.error?.message??'The original native operation is unavailable.';return result;}
 async function updateBlock(b,values){if(session.blockId!==b.id){const result=await run('block.select',{blockId:b.id});if(result?.status!=='applied'||!owned()||!entry?.blocks.includes(b))return;}await run('block.update',{values});}
 function key(e){if(!owned()||!active||!available)return;const typing=['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName);if((e.ctrlKey||e.metaKey)&&!e.altKey){const k=e.key.toLowerCase();if(k==='s'){e.preventDefault();run(e.shiftKey?'panel':'save',e.shiftKey?{panel:'save'}:{});}else if(k==='n'){e.preventDefault();run('entry.add');}else if(k==='o'){e.preventDefault();run('open');}else if(k==='z'&&!typing){e.preventDefault();run(e.shiftKey?'redo':'undo');}else if(k==='b'&&!typing&&block){e.preventDefault();run('block.update',{values:{bold:!block.bold}});}}if(e.key==='Escape'){passphrase='';run('panel',{panel:'none'});}}
 async function unlock(){const entered=passphrase;passphrase='';await run('unlock',{passphrase:entered});}
 async function configure(){const entered=passphrase;passphrase='';await run('lock.configure',{passphrase:entered});}
 async function menuClick(item){if(!item.enabled)return;const result=await run('menu',{menuId:null});if(result?.status==='applied'&&owned())await run(item.command.slice(8),item.payload);}
 onMount(()=>{originalState=journalState;originalProfile=profile;originalWindow=actualWindow;originalController=controller;originalSession=session;originalId=windowId;const view=createJournalNativeView({getRoot:()=>root,getState:()=>journalState,getSession:()=>session,getProfile:()=>profile,getWindow:()=>actualWindow,getController:()=>controller,windowId,available:()=>owned()&&available&&active,tick,getMenus:()=>journalMenus(profile,journalState,windowId)});registerView?.(windowId,view);mounted=true;return()=>{retired=true;view.destroy();mediaNodes.forEach(node=>node.pause());mediaNodes.clear();registerView?.(originalId,null,view);};});
</script>
<section bind:this={root} class="journal-app" class:legacy={cap.legacy} class:windows={cap.windows} class:golden={cap.golden} class:inactive={!active} data-journal-window-id={windowId} data-profile={profile.id} role="region" aria-label={cap.label} tabindex="-1" onkeydown={key}>
 <header class="journal-titlebar">{#if !cap.windows}<WindowControls active={active} onclose={()=>run('close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} onsplitbegin={controls.onsplitbegin} onsplitside={controls.onsplitside} ongreenmenu={controls.ongreenmenu} fullScreen={controls.fullScreen} revealedTop={controls.revealedTop} modernGreenMenu={controls.modernGreenMenu} zoomed={controls.zoomed}/>{/if}<strong>{session?.locked?cap.label:doc?.content.title??cap.label}</strong><small>{!session?.locked&&doc?.dirty?'Edited':''}</small><span></span>{#if cap.windows}<button aria-label="Minimize" disabled={!available||!active||!controls.onminimize} onclick={controls.onminimize}>−</button><button aria-label="Maximize or restore" disabled={!available||!active||!controls.onzoom} onclick={controls.onzoom}>□</button><button aria-label="Close" onclick={()=>run('close')}>×</button>{/if}</header>
 {#if cap.windows}<nav class="journal-menubar" aria-label="Local application menus">{#each menus as menu}<button data-journal-control={`menu:${menu.id}`} onclick={()=>run('menu',{menuId:session?.menu===menu.id?null:menu.id})}>{menu.label}</button>{/each}</nav>{/if}
 {#if session?.menu}<div class="journal-menu" role="menu">{#each menus.find(m=>m.id===session.menu)?.items??[] as item}<button role="menuitem" disabled={!item.enabled} data-journal-control={`menuitem:${item.id}`} onclick={()=>menuClick(item)}>{item.checked?'✓ ':''}{item.label}</button>{/each}</div>{/if}
 {#if session?.locked}<main class="journal-locked"><div class="journal-lock-symbol" aria-hidden="true">▣</div><h2>Your journal is locked</h2><p>Enter your local Journal passphrase. This app access lock is not encryption or Touch ID.</p><form onsubmit={e=>{e.preventDefault();unlock();}}><label>Passphrase<input data-journal-control="unlock-passphrase" type="password" maxlength="256" autocomplete="off" bind:value={passphrase}/></label><button data-journal-control="unlock" class="journal-primary" disabled={!passphrase||!available||!active}>Unlock Journal</button></form></main>
 {:else}
 <div class="journal-toolbar" inert={!available||!active||session?.panel!=='none'}><button data-journal-control="new-entry" onclick={()=>run('entry.add')} disabled={!doc}>＋ New Entry</button><button data-journal-control="attach" onclick={()=>run('attachment.add')} disabled={!entry}>▧ Add Attachment</button><button data-journal-control="suggestions" onclick={()=>run('panel',{panel:'attachments'})} disabled={!entry}>Local Suggestions</button><span></span><button data-journal-control="undo" disabled={!doc?.undo.length} onclick={()=>run('undo')}>↶</button><button data-journal-control="redo" disabled={!doc?.redo.length} onclick={()=>run('redo')}>↷</button><button data-journal-control="save" disabled={!doc} onclick={()=>run('save')}>Save</button><button data-journal-control="share" disabled={!doc} onclick={()=>run('share')}>⇧ Share</button><button data-journal-control="preferences" onclick={()=>run('panel',{panel:'preferences'})}>Settings</button></div>
 <div class="journal-workspace" inert={!available||!active||session?.panel!=='none'}>
  <aside class="journal-sidebar"><h2>Journals</h2>{#each journalState.documents as d (d.id)}<button data-journal-control={`journal:${d.id}`} class:selected={doc===d} onclick={()=>run('document.select',{documentId:d.id})}><span class="journal-book" aria-hidden="true">▥</span>{d.content.title}<small>{d.content.entries.length}</small></button>{/each}<button data-journal-control="new-journal" onclick={()=>run('new')}>＋ New Journal</button><button data-journal-control="open" onclick={()=>run('open')}>Open .jjournal…</button><h2>Entries</h2>{#each [{id:'all',label:'All Entries'},{id:'bookmarked',label:'Bookmarked'},{id:'attachments',label:'With Attachments'}] as filter}<button data-journal-control={`filter:${filter.id}`} class:selected={session?.filter===filter.id} onclick={()=>run('view',{filter:filter.id})}>{filter.label}</button>{/each}<div class="journal-sidebar-bottom"><button data-journal-control="lock" disabled={!journalState.preferences.passHash} onclick={()=>run('lock')}>Lock Journal</button><small>Only local authored moments.<br/>No iCloud or AI suggestions.</small></div></aside>
  <section class="journal-entry-list" aria-label="Journal entries"><label class="journal-search">Search<input data-journal-control="search" type="search" value={session?.search??''} oninput={e=>run('view',{search:e.currentTarget.value})} placeholder="Search your journal"/></label><label class="journal-month">Month<input data-journal-control="month" type="month" value={session?.month??''} onchange={e=>run('view',{month:e.currentTarget.value})}/></label><div class="journal-entry-scroll" data-journal-area="entries">{#each entries as e (e.id)}<button class="journal-entry-card" class:selected={entry===e} data-journal-control={`entry:${e.id}`} data-journal-entry={e.id} onclick={()=>run('entry.select',{entryId:e.id})}><time>{e.date}</time><strong>{e.bookmark?'◆ ':''}{e.title}</strong><p>{e.blocks.map(b=>b.text).join(' ').slice(0,160)||'Start writing your entry…'}</p>{#if e.attachments.length}<small>{e.attachments.length} attachment{e.attachments.length===1?'':'s'}</small>{/if}</button>{/each}{#if !entries.length}<p class="journal-no-entries">No entries match this view.</p>{/if}</div></section>
  <main class="journal-editor" data-journal-area="editor">{#if entry}<div class="journal-entry-heading"><label>Entry date<input data-journal-control="entry-date" type="date" value={entry.date} onchange={e=>run('entry.update',{date:e.currentTarget.value})}/></label><button data-journal-control="bookmark" class:selected={entry.bookmark} aria-label={entry.bookmark?'Remove bookmark':'Bookmark entry'} onclick={()=>run('entry.update',{bookmark:!entry.bookmark})}>{entry.bookmark?'◆':'◇'}</button></div><input class="journal-entry-title" data-journal-control="entry-title" aria-label="Entry title" maxlength="256" value={entry.title} onchange={e=>run('entry.update',{title:e.currentTarget.value})}/>
  <div class="journal-formatbar"><select data-journal-control="block-kind" aria-label="Block style" value={block?.kind??'paragraph'} disabled={!block} onchange={e=>run('block.update',{values:{kind:e.currentTarget.value}})}>{#each ['paragraph','heading','quote','bullet'] as kind}<option value={kind}>{kind}</option>{/each}</select><button data-journal-control="bold" class:selected={block?.bold} disabled={!block} onclick={()=>run('block.update',{values:{bold:!block.bold}})}><b>B</b></button><button data-journal-control="italic" class:selected={block?.italic} disabled={!block} onclick={()=>run('block.update',{values:{italic:!block.italic}})}><i>I</i></button><button data-journal-control="underline" class:selected={block?.underline} disabled={!block} onclick={()=>run('block.update',{values:{underline:!block.underline}})}><u>U</u></button><select data-journal-control="font" aria-label="Typeface from scene Font Book" disabled={!block} value={block?.font??'system-ui'} onchange={e=>run('block.update',{values:{font:e.currentTarget.value}})}><option value="system-ui">System</option>{#each sources.fonts as font}<option value={fontCSSFamily(font)}>{font.family} · {font.style}</option>{/each}</select><input data-journal-control="font-size" aria-label="Font size" type="number" min="8" max="72" value={block?.size??16} disabled={!block} onchange={e=>run('block.update',{values:{size:Number(e.currentTarget.value)}})}/><input data-journal-control="text-color" aria-label="Text color" type="color" value={block?.color??'#292733'} disabled={!block} onchange={e=>run('block.update',{values:{color:e.currentTarget.value}})}/></div>
  {#each entry.blocks as b (b.id)}
   <div class="journal-rich-block" class:selected={b===block} class:quote={b.kind==='quote'} class:bullet={b.kind==='bullet'} data-journal-block={b.id}>
    <textarea data-journal-control={`block:${b.id}`} aria-label={`Edit ${b.kind} block`} maxlength="32768" value={b.text} rows={Math.max(2,Math.min(20,b.text.split('\n').length+Math.ceil(b.text.length/64)))} style={`font-family:${renderFont(b.font)};font-size:${b.size}px;font-weight:${b.bold?'bold':'normal'};font-style:${b.italic?'italic':'normal'};text-decoration:${b.underline?'underline':'none'};color:${b.color};`} onfocus={()=>session.blockId===b.id?null:run('block.select',{blockId:b.id})} oninput={e=>updateBlock(b,{text:e.currentTarget.value})} placeholder="Write about your day…"></textarea>
   </div>
  {/each}
  <div class="journal-block-actions"><button data-journal-control="add-block" onclick={()=>run('block.add')}>＋ Paragraph</button><button data-journal-control="delete-block" disabled={entry.blocks.length<2} onclick={()=>run('block.delete')}>Remove Selected Block</button></div>
  {#each entry.attachments as a (a.id)}
   <figure class="journal-attachment">
    {#if a.mime.startsWith('image/')}<img src={a.content} alt={a.name}/>
    {:else if a.mime.startsWith('audio/')}<audio data-journal-media={a.id} src={a.content} preload="metadata" onloadedmetadata={e=>rememberMedia(e,a)}></audio>
    {:else if a.mime.startsWith('video/')}<video data-journal-media={a.id} src={a.content} preload="metadata" onloadedmetadata={e=>rememberMedia(e,a)}></video>
    {:else if a.mime==='text/plain'}<pre>{a.content}</pre>
    {:else}<p>▤ Actual PDF attachment · use Export Attachment to open its original bytes.</p>{/if}
    {#if a.mime.startsWith('audio/')||a.mime.startsWith('video/')}<div class="journal-media-actions"><button data-journal-control={`attachment-play:${a.id}`} onclick={()=>run('attachment.play',{attachmentId:a.id,playing:true})}>▶ Play</button><button data-journal-control={`attachment-pause:${a.id}`} onclick={()=>run('attachment.play',{attachmentId:a.id,playing:false})}>Ⅱ Pause</button></div>{/if}
    <figcaption><span>{a.name}<small>Retained original {a.source}{a.sourceRevision===null?' · source supplied no revision':` revision ${a.sourceRevision}`}</small></span><button data-journal-control={`attachment-export:${a.id}`} onclick={()=>run('attachment.export',{attachmentId:a.id})}>Export Attachment</button><button data-journal-control={`attachment-remove:${a.id}`} onclick={()=>run('attachment.remove',{attachmentId:a.id})}>Remove</button></figcaption>
   </figure>
  {/each}
  <div class="journal-editor-actions"><button data-journal-control="print" onclick={()=>run('print')}>Print…</button><button data-journal-control="export" onclick={()=>run('panel',{panel:'export'})}>Export…</button><button data-journal-control="delete-entry" onclick={()=>run('entry.delete')}>Delete Entry</button></div>
  {:else}<div class="journal-empty"><h2>A place for your thoughts</h2><p>Create an entry to capture a moment with rich text and genuine local attachments.</p><button class="journal-primary" data-journal-control="create-entry" onclick={()=>doc?run('entry.add'):run('new')}>New Entry</button></div>{/if}</main>
 </div>{/if}
 {#if session?.panel!=='none'}<div class="journal-sheet-backdrop"><section class="journal-sheet" role="dialog" aria-modal="true" aria-label={session?.panel==='close'?'Save Journal Changes':session?.panel==='preferences'?'Journal Settings':session?.panel==='attachments'?'Local Suggestions':session?.panel==='help'?'Journal Help':'Export or Save Journal'}>
 {#if session?.panel==='close'}<h2>Save changes to “{doc?.content.title}”?</h2><p>Save preserves rich entries and actual attachment bytes in the disclosed custom .jjournal format.</p><div class="journal-sheet-buttons"><button data-journal-control="close-discard" onclick={()=>run('close',{decision:'discard'})}>Don't Save</button><button data-journal-control="close-cancel" onclick={()=>run('close',{decision:'cancel'})}>Cancel</button><button data-journal-control="close-save" class="journal-primary" onclick={()=>run('close',{decision:'save'})}>Save</button></div>
 {:else if session?.panel==='save'||session?.panel==='export'}<h2>{session.panel==='save'?'Save Journal As':'Export Your Journal'}</h2><label>Name<input data-journal-control="output-name" maxlength="240" bind:value={name}/></label>{#if session.panel==='export'}<label>Format<select data-journal-control="export-format" bind:value={format}><option value="html">Portable HTML · rich text + original attachment bytes</option><option value="pdf">PDF · genuine static rendered pages</option><option value="jjournal">JesterOS Journal (.jjournal) · custom editable JSON</option></select></label>{/if}<p>No native Apple Journal archive format is claimed. HTML and .jjournal retain original bytes; PDF renders images and text, with explicit static labels for other attachments. PDF uses available scene fonts with browser system fallback, not an Apple document renderer.</p><div class="journal-sheet-buttons"><button data-journal-control="output-cancel" onclick={()=>run('panel',{panel:'none'})}>Cancel</button><button data-journal-control="output-confirm" class="journal-primary" disabled={!name.trim()} onclick={()=>session.panel==='save'?run('save',{name,saveAs:true}):run('export',{format,name})}>{session.panel==='save'?'Save .jjournal':'Export'}</button></div>
 {:else if session?.panel==='preferences'}<h2>Journal Settings</h2><label>Journal name<input data-journal-control="journal-name" maxlength="256" value={doc?.content.title??''} disabled={!doc} onchange={e=>run('document.rename',{title:e.currentTarget.value})}/></label><label class="journal-check"><input data-journal-control="photo-suggestions" type="checkbox" checked={journalState.preferences.photoSuggestions} onchange={e=>run('preferences',{photoSuggestions:e.currentTarget.checked})}/>Show local Photos suggestions</label><label class="journal-check"><input data-journal-control="file-suggestions" type="checkbox" checked={journalState.preferences.fileSuggestions} onchange={e=>run('preferences',{fileSuggestions:e.currentTarget.checked})}/>Show local File suggestions</label><p>Suggestions require a separate explicit Journal Photos/Files grant in the scene Privacy settings. These are actual visible scene sources, not inferred moments. No host data is scanned.</p><label class="journal-check"><input data-journal-control="lock-on-close" type="checkbox" checked={journalState.preferences.lockOnClose} onchange={e=>run('preferences',{lockOnClose:e.currentTarget.checked})}/>Lock all remaining windows when a Journal window closes</label>{#if !journalState.preferences.passHash}<label>New local passphrase (8 characters minimum)<input data-journal-control="configure-passphrase" type="password" maxlength="256" autocomplete="off" bind:value={passphrase}/></label><button data-journal-control="configure-lock" disabled={passphrase.length<8} onclick={configure}>Configure App Access Lock</button>{:else}<button data-journal-control="settings-lock" onclick={()=>run('lock')}>Lock Now</button>{/if}<p>The lock is a local app access barrier, not encrypted storage, a host login or Touch ID. Raw scene state and saved copies remain readable.</p><button data-journal-control="settings-done" onclick={()=>run('panel',{panel:'none'})}>Done</button>
 {:else if session?.panel==='attachments'}<h2>Local Suggestions</h2><p>Only actual visible Photos and original live Files appear after app opt-in and explicit scene Privacy permission. Hidden/deleted sources are excluded.</p><div class="journal-suggestions" data-journal-area="suggestions">{#each sources.photos as photo (photo.id)}<button data-journal-control={`photo:${photo.id}`} onclick={()=>run('attachment.add',{photoId:photo.id})}><img src={photo.editedContent??photo.content} alt={photo.title}/><span>{photo.title}</span></button>{/each}{#each sources.files as file (file.id)}<button data-journal-control={`file:${file.id}`} onclick={()=>run('attachment.add',{fileId:file.id})}><b>▤</b><span>{file.name}</span></button>{/each}</div>{#if !sources.photos.length&&!sources.files.length}<p>No permitted local suggestions. Enable Journal suggestions and allow Journal Photos/Files in scene Privacy, or choose a File explicitly.</p>{/if}<div class="journal-sheet-buttons"><button data-journal-control="suggestions-choose" onclick={()=>run('attachment.add')}>Choose File…</button><button data-journal-control="suggestions-done" onclick={()=>run('panel',{panel:'none'})}>Done</button></div>
 {:else}<h2>{cap.label}</h2><p>{cap.disclosure}</p><p>Create separate journals, edit dated entries, search/filter and bookmark them. Each rich text block has explicit style and original Font Book typeface choices. Undo/redo retains up to 12 content edits. Add genuine Files or permitted visible Photos; attachments are byte snapshots with original source identities/revisions, not a second Photos library.</p><p>Save/open .jjournal uses a custom portable JSON envelope. HTML retains formatting and media; genuine PDF is static raster pages. Dirty journals prompt Save/Don't Save/Cancel before closing.</p><button data-journal-control="help-done" onclick={()=>run('panel',{panel:'none'})}>Done</button>{/if}
 {#if message}<p class="journal-error" role="alert">{message}</p>{/if}</section></div>{/if}
 <footer class="journal-status" role="status"><span>{message||cap.disclosure}</span>{#if !session?.locked}<small>{entries.length} entries</small>{/if}</footer>
</section>
